<template>
  <div class="payment-term-mapping-table q-mb-xl">
    <div class="row items-center q-mb-sm">
      <div class="text-subtitle2">{{ $t('payment_term_mapping_overwrites') }}</div>
      <q-space />
      <f-btn
        :label="$t('add_mapping')"
        icon="add"
        @click="showAddDialog = true"
      />
    </div>

    <q-table
      :rows="rows"
      :columns="columns"
      row-key="id"
      flat
      bordered
      dense
      binary-state-sort
      :pagination="{ rowsPerPage: 0 }"
      hide-bottom
    >
      <template v-slot:body-cell-actions="props">
        <q-td :props="props" class="text-right">
          <q-btn
            flat
            round
            dense
            color="negative"
            icon="delete"
            @click="confirmDelete(props.row)"
          >
            <q-tooltip>{{ $t('delete') }}</q-tooltip>
          </q-btn>
        </q-td>
      </template>
    </q-table>

    <!-- Add Dialog -->
    <q-dialog v-model="showAddDialog" persistent>
      <q-card style="min-width: 400px">
        <q-card-section>
          <div class="text-h6">{{ $t('add_payment_term_mapping') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-input
            v-model="newEntry.code"
            :label="$t('erp_code')"
            outlined
            dense
            class="q-mb-md"
            autofocus
          />
          <q-select
            v-model="newEntry.term_type"
            :options="termTypeOptions"
            :label="$t('term_type')"
            outlined
            dense
            emit-value
            map-options
            class="q-mb-md"
          />
          <q-input
            v-model.number="newEntry.days"
            :label="$t('days')"
            type="number"
            outlined
            dense
            class="q-mb-md"
          />
          <q-input
            v-model="newEntry.description"
            :label="$t('description')"
            outlined
            dense
          />
        </q-card-section>

        <q-card-actions align="right" class="text-primary">
          <q-btn flat :label="$t('Cancel')" v-close-popup />
          <q-btn flat :label="$t('Add')" @click="addEntry" v-close-popup />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { useQuasar } from 'quasar';
import { i18n } from 'src/boot/i18n';
import { invoiceCalculationApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions';

const $q = useQuasar();

interface PaymentTermMapping {
  id: string;
  code: string;
  term_type: string;
  days: number;
  description: string | null;
}

const rows = ref<PaymentTermMapping[]>([]);
const showAddDialog = ref(false);
const newEntry = ref({
  code: '',
  term_type: 'net',
  days: 0,
  description: '',
});

const termTypeOptions = [
  { label: 'Net (Standard)', value: 'net' },
  { label: 'Receipt (Immediate)', value: 'receipt' },
  { label: 'DOM (Day of Month)', value: 'dom' },
  { label: 'EOM (End of Month)', value: 'eom' },
];

const columns = [
  {
    name: 'code',
    label: i18n.t('code'),
    field: 'code',
    align: 'left',
    sortable: true,
  },
  {
    name: 'term_type',
    label: i18n.t('term_type'),
    field: 'term_type',
    align: 'left',
    sortable: true,
  },
  {
    name: 'days',
    label: i18n.t('days'),
    field: 'days',
    align: 'left',
    sortable: true,
  },
  {
    name: 'description',
    label: i18n.t('description'),
    field: 'description',
    align: 'left',
    sortable: true,
  },
  {
    name: 'actions',
    label: '',
    field: 'actions',
    align: 'right',
  },
] as any;

const fetchMappings = async () => {
  try {
    const response = await invoiceCalculationApiService.listPaymentTermMappings();

    if (response && response.success && Array.isArray(response.data)) {
      rows.value = response.data;
    }
  } catch (error) {
    console.error('Failed to fetch payment term mappings:', error);
  }
};

onMounted(() => {
  fetchMappings();
});

const addEntry = async () => {
  if (!newEntry.value.code) return;

  try {
    const response =
      await invoiceCalculationApiService.upsertPaymentTermMapping(
        newEntry.value.code,
        newEntry.value.term_type,
        newEntry.value.days,
        newEntry.value.description || undefined,
      );

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n
      throw response;
    }

    notify.success(i18n.t('mapping_added_successfully'));
    fetchMappings();
  } catch (error) {
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_add_failed'),
    );
  } finally {
    newEntry.value = { code: '', term_type: 'net', days: 0, description: '' };
  }
};

const confirmDelete = (row: PaymentTermMapping) => {
  $q.dialog({
    title: i18n.t('confirm'),
    message: i18n.t('delete_mapping_confirm'),
    cancel: true,
    persistent: true,
  }).onOk(() => {
    deleteEntry(row);
  });
};

const deleteEntry = async (row: PaymentTermMapping) => {
  try {
    const response =
      await invoiceCalculationApiService.deletePaymentTermMapping(row.id);

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n.
      throw response;
    }

    notify.success(i18n.t('mapping_deleted_successfully'));
    fetchMappings();
  } catch (error) {
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_delete_failed'),
    );
  }
};
</script>