<script setup lang="ts">
import { ref, onMounted, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { notify } from 'src/components/notifications/notify';
import { useSettingStore } from 'src/store/main';
import { preferencesService } from 'src/services/preferences/preferencesService';
import DiscountMappingTable from './DiscountMappingTable.vue';
import PaymentTermMappingTable from './PaymentTermMappingTable.vue';
import CalculatedFieldsSettings from './CalculatedFieldsSettings.vue';

const PREF_AP_FIELD = 'AP_ASSIGNMENT_CODE_FIELD';
// DRFS-620: one org-wide setting controls how invoice AND discount due dates
// are rolled when they land on a weekend. Mirror of the backend convention
// tokens in helpers/payment_term_calculator.py.
const PREF_WEEKEND_CONVENTION = 'DUE_DATE_WEEKEND_CONVENTION';

const settingsStore = useSettingStore();
const { org_based_settings } = storeToRefs(settingsStore);

const apAssignmentCodeField = ref('custom_field_2');
const weekendConvention = ref('none');

const weekendConventionOptions = computed(() => [
  { label: i18n.t('due_date_weekend_none'), value: 'none' },
  { label: i18n.t('due_date_weekend_following'), value: 'following' },
  { label: i18n.t('due_date_weekend_preceding'), value: 'preceding' },
  { label: i18n.t('due_date_weekend_nearest'), value: 'nearest' },
  {
    label: i18n.t('due_date_weekend_modified_following'),
    value: 'modified_following',
  },
]);

const customFieldOptions = [
  { label: 'Custom Field 1', value: 'custom_field_1' },
  { label: 'Custom Field 2', value: 'custom_field_2' },
  { label: 'Custom Field 3', value: 'custom_field_3' },
  { label: 'Custom Field 4', value: 'custom_field_4' },
  { label: 'Custom Field 5', value: 'custom_field_5' },
  { label: 'Custom Field 6', value: 'custom_field_6' },
  { label: 'Custom Field 7', value: 'custom_field_7' },
  { label: 'Custom Field 8', value: 'custom_field_8' },
  { label: 'Custom Field 9', value: 'custom_field_9' },
  { label: 'Custom Field 10', value: 'custom_field_10' },
];

const loadPreferences = async () => {
  try {
    const apFieldVal = await preferencesService.getOrgPreference(PREF_AP_FIELD);
    if (apFieldVal) {
      apAssignmentCodeField.value = apFieldVal;
    }

    const conventionVal = await preferencesService.getOrgPreference(
      PREF_WEEKEND_CONVENTION,
    );
    if (conventionVal) {
      weekendConvention.value = conventionVal;
    }
  } catch (error) {
    console.error('Failed to load due date preferences:', error);
  }
};

onMounted(() => {
  loadPreferences();
});

const savePreferences = async () => {
  try {
    const results = await Promise.all([
      preferencesService.setOrgPreference(
        PREF_AP_FIELD,
        apAssignmentCodeField.value,
      ),
      preferencesService.setOrgPreference(
        PREF_WEEKEND_CONVENTION,
        weekendConvention.value,
      ),
    ]);

    const allSuccess = results.every((r) => r.success);
    if (allSuccess) {
      org_based_settings.value[PREF_AP_FIELD] = apAssignmentCodeField.value;
      org_based_settings.value[PREF_WEEKEND_CONVENTION] =
        weekendConvention.value;
      notify.success(i18n.t('saved_successfully'));
    } else {
      throw new Error('One or more preferences failed to save');
    }
  } catch (error) {
    console.error('Failed to save due date preferences:', error);
    notify.error(i18n.t('save_failed_please_retry'));
  }
};
</script>

