<template>
  <div class="discount-mapping-table q-mb-xl">
    <div class="row items-center q-mb-sm">
      <div class="text-subtitle2">{{ $t('discount_mapping_overwrites') }}</div>
      <q-space />
      <f-btn
        :label="$t('add_mapping')"
        icon="add"
        @click="showAddDialog = true"
      />
    </div>

    <q-table
      :rows="rows"
      :columns="columns"
      row-key="id"
      flat
      bordered
      dense
      binary-state-sort
      :pagination="{ rowsPerPage: 0 }"
      hide-bottom
    >
      <template v-slot:body-cell-percentage="props">
        <q-td :props="props">
          {{ props.row.percentage !== null && props.row.percentage !== undefined ? `${props.row.percentage}%` : '—' }}
        </q-td>
      </template>
      <template v-slot:body-cell-days="props">
        <q-td :props="props">
          {{ props.row.days !== null && props.row.days !== undefined ? props.row.days : '—' }}
        </q-td>
      </template>
      <template v-slot:body-cell-actions="props">
        <q-td :props="props" class="text-right">
          <q-btn
            flat
            round
            dense
            color="negative"
            icon="delete"
            @click="confirmDelete(props.row)"
          >
            <q-tooltip>{{ $t('delete') }}</q-tooltip>
          </q-btn>
        </q-td>
      </template>
    </q-table>

    <!-- Add Dialog -->
    <q-dialog v-model="showAddDialog" persistent>
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ $t('add_discount_overwrite') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-input
            v-model="newEntry.prefix"
            :label="$t('prefix')"
            outlined
            dense
            class="q-mb-md"
            autofocus
          />
          <q-input
            v-model.number="newEntry.percentage"
            :label="$t('percentage')"
            type="number"
            step="0.1"
            outlined
            dense
            class="q-mb-md"
          />
          <q-input
            v-model.number="newEntry.days"
            :label="$t('days')"
            type="number"
            min="0"
            outlined
            dense
          />
        </q-card-section>

        <q-card-actions align="right" class="text-primary">
          <q-btn flat :label="$t('Cancel')" v-close-popup />
          <q-btn flat :label="$t('Add')" @click="addEntry" v-close-popup />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { useQuasar } from 'quasar';
import { i18n } from 'src/boot/i18n';
import { invoiceCalculationApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions';

const $q = useQuasar();

interface DiscountMapping {
  id: string;
  prefix: string;
  percentage: number | null;
  days: number | null;
}

const rows = ref<DiscountMapping[]>([]);
const showAddDialog = ref(false);
const newEntry = ref({
  prefix: '',
  percentage: 0,
  days: null as number | null,
});

const columns = [
  {
    name: 'prefix',
    label: i18n.t('prefix'),
    field: 'prefix',
    align: 'left',
    sortable: true,
  },
  {
    name: 'percentage',
    label: i18n.t('percentage'),
    field: 'percentage',
    align: 'left',
    sortable: true,
  },
  {
    name: 'days',
    label: i18n.t('days'),
    field: 'days',
    align: 'left',
    sortable: true,
  },
  {
    name: 'actions',
    label: '',
    field: 'actions',
    align: 'right',
  },
] as any;

const fetchMappings = async () => {
  try {
    const response = await invoiceCalculationApiService.listDiscountMappings();

    if (response && response.success && Array.isArray(response.data)) {
      rows.value = response.data;
    }
  } catch (error) {
    console.error('Failed to fetch discount mappings:', error);
  }
};

onMounted(() => {
  fetchMappings();
});

const addEntry = async () => {
  if (!newEntry.value.prefix) return;

  try {
    const response = await invoiceCalculationApiService.upsertDiscountMapping(
      newEntry.value.prefix,
      newEntry.value.percentage || null,
      newEntry.value.days,
    );

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n.
      throw response;
    }

    notify.success(i18n.t('mapping_added_successfully'));
    fetchMappings();
  } catch (error) {
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_add_failed'),
    );
  } finally {
    newEntry.value = { prefix: '', percentage: 0, days: null };
  }
};

const confirmDelete = (row: DiscountMapping) => {
  $q.dialog({
    title: i18n.t('confirm'),
    message: i18n.t('delete_mapping_confirm'),
    cancel: true,
    persistent: true,
  }).onOk(() => {
    deleteEntry(row);
  });
};

const deleteEntry = async (row: DiscountMapping) => {
  try {
    const response = await invoiceCalculationApiService.deleteDiscountMapping(
      row.id,
    );

    if (response && response.success === false) {
      // Throw so the catch block runs the response through
      // ApiExceptions.getErrorMessage — which translates error_code via i18n.
      throw response;
    }

    notify.success(i18n.t('mapping_deleted_successfully'));
    fetchMappings();
  } catch (error) {
    notify.error(
      ApiExceptions.getErrorMessage(error as any) ||
        i18n.t('mapping_delete_failed'),
    );
  }
};
</script>